dashboard.definition:
{
  "title": "Comptes AD privilégiés",
  "description": "Tout sur les accès privilégiés : membres de Domain/Enterprise/Schema Admins et des autres groupes sensibles (noms EN + FR), âge et expiration des mots de passe, dernière connexion, résidus adminCount, comptes de service Kerberoastables et changements récents d'appartenance aux groupes privilégiés.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Période",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "title": "Comptes privilégiés (actifs)",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 `adx_risk` | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "Mot de passe sans expiration",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 AND pwd_never_expires=1 `adx_risk` | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "Mot de passe plus ancien que la limite privilégiée",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 AND pwd_age_days>`adx_priv_max_pwd_age_days` `adx_risk` | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "Aucune connexion depuis plus de adx_stale_days jours",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 AND days_since_logon>`adx_stale_days` `adx_risk` | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "adminCount=1 hors groupe privilégié",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 20
          },
          {
            "value": "#B0413E",
            "from": 20
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where is_disabled=0 AND tonumber(mvindex(adminCount,0))=1 AND isnull(priv_groups) AND sam!=\"krbtgt\" `adx_risk` | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "title": "Comptes de service (utilisateurs avec SPN)",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where is_disabled=0 AND isnotnull(servicePrincipalName) AND sam!=\"krbtgt\" `adx_risk` | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_7": {
      "type": "splunk.bar",
      "title": "Membres par groupe privilégié",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "legendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| inputlookup `adx_groups_lookup` | eval grp=coalesce(cn, sAMAccountName, name) | where match(grp,\"(?i)^(`adx_priv_group_names`)(?![\\\\w -])\") | stats max(membercount) as members by grp | sort - members",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_8": {
      "type": "splunk.table",
      "title": "Groupes privilégiés",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "description": "Membres directs d'après le lookup des groupes (groupes imbriqués non développés ; adminCount couvre les membres indirects).",
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| inputlookup `adx_groups_lookup` | eval grp=coalesce(cn, sAMAccountName, name) | where match(grp,\"(?i)^(`adx_priv_group_names`)(?![\\\\w -])\") | eval members=membercount | sort - members | table grp members groupType_Name OU | rename grp as \"Groupe\", members as \"Membres\", groupType_Name as \"Type de groupe\", OU as \"OU\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_9": {
      "type": "splunk.table",
      "title": "Comptes privilégiés (actifs)",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "count": 12,
        "wrap": true,
        "columnFormat": {
          "MdP sans expiration": {
            "rowBackgroundColors": "> table | seriesByName(\"MdP sans expiration\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "context": {
        "col0ColorConfig": [
          {
            "match": "OUI",
            "value": "#B0413E"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` `adx_risk` | where sam=\"$row.Compte.value$\" | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_10": {
      "type": "splunk.table",
      "title": "adminCount=1 sans appartenance privilégiée (résidus AdminSDHolder)",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "description": "Comptes autrefois privilégiés : AD conserve adminCount=1 et bloque l'héritage des permissions. À nettoyer avec SDProp après revue.",
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` `adx_risk` | where sam=\"$row.Compte.value$\" | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_11": {
      "type": "splunk.table",
      "title": "Comptes de service (SPN) - mots de passe les plus anciens d'abord",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "count": 8,
        "wrap": true,
        "columnFormat": {
          "Privilégié": {
            "rowBackgroundColors": "> table | seriesByName(\"Privilégié\") | matchValue(col0ColorConfig)"
          },
          "MdP sans expiration": {
            "rowBackgroundColors": "> table | seriesByName(\"MdP sans expiration\") | matchValue(col1ColorConfig)"
          }
        }
      },
      "description": "Les comptes utilisateurs avec un SPN sont des cibles de Kerberoasting : privilégiez des mots de passe longs et aléatoires ou des gMSA.",
      "context": {
        "col0ColorConfig": [
          {
            "match": "OUI",
            "value": "#F8BE34"
          }
        ],
        "col1ColorConfig": [
          {
            "match": "OUI",
            "value": "#B0413E"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` `adx_risk` | where sam=\"$row.Compte.value$\" | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_12": {
      "type": "splunk.table",
      "title": "Changements récents d'appartenance aux groupes privilégiés",
      "dataSources": {
        "primary": "ds_12"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "description": "Suit le sélecteur de période.",
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` `adx_normalize` | search is_group_event=1 | where match(group_name,\"(?i)^(`adx_priv_group_names`)(?![\\\\w -])\") | lookup adx_event_catalog event_id OUTPUT action | rename actor_user as changed_by, target_user as member | sort - _time | table _time action group_name member changed_by dc | rename _time as \"Heure\", action as \"Action\", group_name as \"Groupe\", member as \"Membre\", changed_by as \"Modifié par\", dc as \"DC\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "Comptes privilégiés (actifs)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Mot de passe sans expiration",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 AND pwd_never_expires=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Mot de passe plus ancien que la limite privilégiée",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 AND pwd_age_days>`adx_priv_max_pwd_age_days` | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Aucune connexion depuis plus de adx_stale_days jours",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 AND days_since_logon>`adx_stale_days` | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "adminCount=1 hors groupe privilégié",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND tonumber(mvindex(adminCount,0))=1 AND isnull(priv_groups) AND sam!=\"krbtgt\" | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Comptes de service (utilisateurs avec SPN)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND isnotnull(servicePrincipalName) AND sam!=\"krbtgt\" | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Membres par groupe privilégié",
      "options": {
        "query": "| inputlookup `adx_groups_lookup` | eval grp=coalesce(cn, sAMAccountName, name) | where match(grp,\"(?i)^(`adx_priv_group_names`)(?![\\\\w -])\") | stats max(membercount) as members by grp | sort - members",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Groupes privilégiés",
      "options": {
        "query": "| inputlookup `adx_groups_lookup` | eval grp=coalesce(cn, sAMAccountName, name) | where match(grp,\"(?i)^(`adx_priv_group_names`)(?![\\\\w -])\") | eval members=membercount | sort - members | table grp members groupType_Name OU | rename grp as \"Groupe\", members as \"Membres\", groupType_Name as \"Type de groupe\", OU as \"OU\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Comptes privilégiés (actifs)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 | eval never_expires=if(pwd_never_expires=1,\"OUI\",\"non\"), smartcard=if(smartcard_required=1,\"yes\",\"non\"), last_logon=strftime(last_logon,\"%Y-%m-%d\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d\"), groups=mvjoin(priv_groups,\", \") | sort - pwd_age_days | table sam display_name groups pwd_set pwd_age_days never_expires smartcard last_logon days_since_logon ou | rename sam as \"Compte\", display_name as \"Nom affiché\", groups as \"Groupes privilégiés\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", never_expires as \"MdP sans expiration\", smartcard as \"Carte à puce\", last_logon as \"Dernière connexion\", days_since_logon as \"Jours sans connexion\", ou as \"OU\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "adminCount=1 sans appartenance privilégiée (résidus AdminSDHolder)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND tonumber(mvindex(adminCount,0))=1 AND isnull(priv_groups) AND sam!=\"krbtgt\" | eval last_logon=strftime(last_logon,\"%Y-%m-%d\") | table sam display_name pwd_age_days last_logon ou | rename sam as \"Compte\", display_name as \"Nom affiché\", pwd_age_days as \"Âge du mot de passe (j)\", last_logon as \"Dernière connexion\", ou as \"OU\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Comptes de service (SPN) - mots de passe les plus anciens d'abord",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND isnotnull(servicePrincipalName) AND sam!=\"krbtgt\" | eval spn_count=mvcount(servicePrincipalName), privileged=if(is_privileged=1,\"OUI\",\"non\"), enc=coalesce('msDS-SupportedEncryptionTypes',\"default (RC4)\"), never_expires=if(pwd_never_expires=1,\"OUI\",\"non\"), last_logon=strftime(last_logon,\"%Y-%m-%d\") | sort - pwd_age_days | table sam display_name spn_count pwd_age_days never_expires privileged enc last_logon ou | rename sam as \"Compte\", display_name as \"Nom affiché\", spn_count as \"Nb SPN\", pwd_age_days as \"Âge du mot de passe (j)\", never_expires as \"MdP sans expiration\", privileged as \"Privilégié\", enc as \"Chiffrement Kerberos\", last_logon as \"Dernière connexion\", ou as \"OU\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "Changements récents d'appartenance aux groupes privilégiés",
      "options": {
        "query": "`adx_security_events` `adx_normalize` | search is_group_event=1 | where match(group_name,\"(?i)^(`adx_priv_group_names`)(?![\\\\w -])\") | lookup adx_event_catalog event_id OUTPUT action | rename actor_user as changed_by, target_user as member | sort - _time | table _time action group_name member changed_by dc | rename _time as \"Heure\", action as \"Action\", group_name as \"Groupe\", member as \"Membre\", changed_by as \"Modifié par\", dc as \"DC\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    }
  },
